contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address caller) public payable {
        require(caller == address(this) || caller != address(this), "caller is arbitrary");

        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        // The owner is this test contract because it deployed c, so withdrawAll must never revert.
        assert(!reverted && balanceAfter == 0 && depositsAfter == depositsBefore);
    }
}

