pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller) internal {
        vm.assume(caller == address(this) || caller != address(this));
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        assertTrue(!reverted && balanceAfter == 0 && depositsAfter == depositsBefore);
    }

    function testFuzz_run(address caller) public {
